<style scoped lang="scss" src="./search-button.scss"></style>

<script>
import { Component, Vue, Prop } from "vue-property-decorator";
import Icon from "../icon/icon.vue";
import { IconShape } from "../../components/icon/icon.constants.js";

@Component({
  components: {
    Icon
  }
})
export default class SearchButton extends Vue {
  @Prop({ type: String, default: "" }) value;
  @Prop({ type: String, default: "" }) placeholder;
  @Prop({ type: Boolean, default: false }) alwaysOpen;

  focus = false;
  open = false;
  hovered = false;

  handleClick() {
    if (!this.open && !this.alwaysOpen) {
      this.open = true;
      setTimeout(() => {
        this.$refs.input.focus();
      }, 200);
    }

    this.focus = true;
  }

  handleBlur() {
    if (!this.alwaysOpen && !this.hovered) {
      this.open = false;
    }

    if (!this.hovered) {
      this.focus = false;
    }
  }

  handleChange(event) {
    this.$emit("input", event.target.value);
  }

  handleMouseOver() {
    this.hovered = true;
  }

  handleMouseOut() {
    this.hovered = false;
  }

  get IconShape() {
    return IconShape;
  }

  get buttonOpenClass() {
    return this.open || this.alwaysOpen
      ? "SearchButton--buttonOpen"
      : "SearchButton--buttonClose";
  }

  get hoveredClass() {
    return this.hovered && !this.alwaysOpen && !this.open
      ? "SearchButton--hovered"
      : "SearchButton--unhovered";
  }

  get focusClass() {
    return this.focus ? "SearchButton--focus" : "SearchButton--unfocus";
  }

  get inputOpenClass() {
    return this.open || this.alwaysOpen
      ? "SearchButton--inputOpen"
      : "SearchButton--inputClose";
  }
}
</script>

<template>
  <div
    :class="['SearchButton', buttonOpenClass, hoveredClass, focusClass]"
    @click="handleClick"
    @mouseover="handleMouseOver"
    @mouseout="handleMouseOut"
  >
    <Icon class="SearchButton__Icon" :shape="IconShape.SEARCH_2" :size="25" />
    <input
      ref="input"
      :value="value"
      :placeholder="placeholder"
      @blur="handleBlur"
      @input="handleChange"
      :class="['SearchButton__Input', inputOpenClass]"
    />
  </div>
</template>
